DATA = {'root': {'title': 'TypeScript 7.1 adds import attributes to ambient modules', 'description': 'TypeScript 7.1 can match pattern ambient module declarations by import attributes, enabling attribute-aware module typing.', 'published': '**Published:** September 1, 2026', 'summary': 'Pattern ambient modules can now declare import-attribute types, so TypeScript can select typings according to attributes on an import.', 'what': "TypeScript's native compiler now supports import-attribute types on pattern ambient module declarations. This lets declarations distinguish imports by attributes such as `type: 'css'` or `type: 'text'`.", 'matching': 'When an import carries attributes, TypeScript can resolve it against a matching pattern ambient module. Matching uses assignability, and when more than one declaration matches, TypeScript chooses the declaration with the most specific attribute type.', 'limits': 'For now, attribute types on these declarations are limited to regular properties whose values are string literal types. Declarations with the same pattern and identical attribute types can merge; declarations with different attribute types remain distinct.', 'compat': 'The change was merged for the TypeScript 7.1.0 Beta milestone. It does not add built-in CSS or text import declarations to the standard library, so projects and tooling still define the ambient modules they need.', 'head_changed': 'What changed', 'head_compat': 'Compatibility', 'head_source': 'Source', 'source_intro': 'Read the merged TypeScript pull request:'}, 'zh-cn': {'title': 'TypeScript 7.1 为环境模块添加导入属性', 'description': 'TypeScript 7.1 可按导入属性匹配模式环境模块声明，从而支持基于属性的模块类型解析。', 'published': '**发布日期：** 2026 年 9 月 1 日', 'summary': '模式环境模块现在可以声明导入属性类型，使 TypeScript 能根据 import 上的属性选择对应的类型声明。', 'what': "TypeScript 的原生编译器现在支持在模式环境模块声明上指定导入属性类型。这使声明可以根据 `type: 'css'`、`type: 'text'` 等属性区分不同导入。", 'matching': '当 import 带有属性时，TypeScript 可以将其解析到匹配的模式环境模块。匹配基于可赋值性；如果多个声明都匹配，TypeScript 会选择属性类型最具体的声明。', 'limits': '目前，这类声明中的属性类型仅允许使用值为字符串字面量类型的普通属性。模式和属性类型完全相同的声明可以合并，而属性类型不同的声明保持独立。', 'compat': '此更改已合并到 TypeScript 7.1.0 Beta 里程碑。标准库并未因此内置 CSS 或文本导入声明，因此项目和工具仍需定义所需的环境模块。', 'head_changed': '主要变化', 'head_compat': '兼容性', 'head_source': '来源', 'source_intro': '阅读已合并的 TypeScript 拉取请求：'}, 'it-it': {'title': 'TypeScript 7.1 aggiunge gli attributi di import ai moduli ambient', 'description': 'TypeScript 7.1 può associare le dichiarazioni di moduli ambient con pattern in base agli attributi di import.', 'published': '**Pubblicato:** 1 settembre 2026', 'summary': 'I moduli ambient con pattern possono ora dichiarare tipi per gli attributi di import, permettendo a TypeScript di scegliere i tipi in base agli attributi dell’import.', 'what': "Il compilatore nativo di TypeScript ora supporta tipi per gli attributi di import nelle dichiarazioni di moduli ambient con pattern. Le dichiarazioni possono così distinguere import con attributi come `type: 'css'` o `type: 'text'`.", 'matching': "Quando un import contiene attributi, TypeScript può risolverlo verso un modulo ambient con pattern corrispondente. La corrispondenza usa l'assegnabilità e, se più dichiarazioni coincidono, TypeScript sceglie quella con il tipo di attributi più specifico.", 'limits': 'Per ora, i tipi degli attributi in queste dichiarazioni sono limitati a proprietà normali con valori di tipo stringa letterale. Le dichiarazioni con lo stesso pattern e tipi di attributi identici possono essere unite; quelle con tipi diversi restano separate.', 'compat': 'La modifica è stata integrata nel milestone TypeScript 7.1.0 Beta. Non aggiunge dichiarazioni integrate per import CSS o di testo alla libreria standard, quindi progetti e strumenti devono ancora definire i moduli ambient necessari.', 'head_changed': 'Cosa è cambiato', 'head_compat': 'Compatibilità', 'head_source': 'Fonte', 'source_intro': 'Leggi la pull request TypeScript integrata:'}, 'pt-br': {'title': 'TypeScript 7.1 adiciona atributos de importação a módulos ambient', 'description': 'O TypeScript 7.1 pode associar declarações de módulos ambient com padrão usando atributos de importação.', 'published': '**Publicado:** 1 de setembro de 2026', 'summary': 'Módulos ambient com padrão agora podem declarar tipos de atributos de importação, permitindo que o TypeScript escolha tipagens conforme os atributos do import.', 'what': "O compilador nativo do TypeScript agora aceita tipos de atributos de importação em declarações de módulos ambient com padrão. Assim, as declarações podem diferenciar imports por atributos como `type: 'css'` ou `type: 'text'`.", 'matching': 'Quando um import possui atributos, o TypeScript pode resolvê-lo para um módulo ambient com padrão correspondente. A correspondência usa atribuibilidade e, quando mais de uma declaração combina, o TypeScript escolhe a que possui o tipo de atributos mais específico.', 'limits': 'Por enquanto, os tipos de atributos nessas declarações são limitados a propriedades comuns cujos valores são tipos literais de string. Declarações com o mesmo padrão e tipos de atributos idênticos podem ser mescladas; tipos diferentes permanecem separados.', 'compat': 'A mudança foi incorporada ao marco TypeScript 7.1.0 Beta. Ela não adiciona declarações integradas de importação de CSS ou texto à biblioteca padrão, portanto projetos e ferramentas ainda precisam definir os módulos ambient necessários.', 'head_changed': 'O que mudou', 'head_compat': 'Compatibilidade', 'head_source': 'Fonte', 'source_intro': 'Leia o pull request do TypeScript que foi incorporado:'}, 'sv-se': {'title': 'TypeScript 7.1 lägger till importattribut i ambient-moduler', 'description': 'TypeScript 7.1 kan matcha mönsterbaserade ambient-moduldeklarationer med hjälp av importattribut.', 'published': '**Publicerad:** 1 september 2026', 'summary': 'Mönsterbaserade ambient-moduler kan nu deklarera typer för importattribut, så att TypeScript kan välja typer utifrån importens attribut.', 'what': "TypeScripts inbyggda kompilator stöder nu typer för importattribut i mönsterbaserade ambient-moduldeklarationer. Deklarationer kan därmed skilja mellan importer med attribut som `type: 'css'` och `type: 'text'`.", 'matching': 'När en import har attribut kan TypeScript lösa den mot en matchande mönsterbaserad ambient-modul. Matchningen använder tilldelningsbarhet och om flera deklarationer matchar väljer TypeScript den med den mest specifika attributtypen.', 'limits': 'För närvarande är attributtyperna begränsade till vanliga egenskaper vars värden är strängliteraltyper. Deklarationer med samma mönster och identiska attributtyper kan slås samman; olika attributtyper hålls åtskilda.', 'compat': 'Ändringen har slagits samman för milstolpen TypeScript 7.1.0 Beta. Den lägger inte till inbyggda CSS- eller textimportdeklarationer i standardbiblioteket, så projekt och verktyg behöver fortfarande definiera de ambient-moduler de behöver.', 'head_changed': 'Vad har ändrats', 'head_compat': 'Kompatibilitet', 'head_source': 'Källa', 'source_intro': 'Läs den sammanslagna TypeScript-pull requesten:'}, 'bg-bg': {'title': 'TypeScript 7.1 добавя import attributes към ambient модули', 'description': 'TypeScript 7.1 може да съпоставя pattern ambient module декларации според import attributes.', 'published': '**Публикувано:** 1 септември 2026 г.', 'summary': 'Pattern ambient модулите вече могат да декларират типове за import attributes, така че TypeScript да избира типизация според атрибутите на import.', 'what': "Нативният компилатор на TypeScript вече поддържа типове за import attributes в pattern ambient module декларации. Така декларациите могат да разграничават import-и с атрибути като `type: 'css'` или `type: 'text'`.", 'matching': 'Когато import съдържа атрибути, TypeScript може да го разреши към съответстващ pattern ambient модул. Съпоставянето използва assignability, а ако има повече от една подходяща декларация, TypeScript избира тази с най-специфичния тип атрибути.', 'limits': 'Засега типовете на атрибутите в тези декларации са ограничени до обикновени свойства със стойности от string literal тип. Декларации с един и същ pattern и идентични типове атрибути могат да се обединяват; различните типове остават отделни.', 'compat': 'Промяната е обединена за milestone TypeScript 7.1.0 Beta. Тя не добавя вградено CSS или text import деклариране в стандартната библиотека, затова проектите и инструментите все още трябва да дефинират нужните ambient модули.', 'head_changed': 'Какво се промени', 'head_compat': 'Съвместимост', 'head_source': 'Източник', 'source_intro': 'Прочетете обединения TypeScript pull request:'}, 'es-es': {'title': 'TypeScript 7.1 añade atributos de importación a módulos ambient', 'description': 'TypeScript 7.1 puede asociar declaraciones de módulos ambient con patrón mediante atributos de importación.', 'published': '**Publicado:** 1 de septiembre de 2026', 'summary': 'Los módulos ambient con patrón ahora pueden declarar tipos de atributos de importación, permitiendo que TypeScript elija tipos según los atributos del import.', 'what': "El compilador nativo de TypeScript ahora admite tipos de atributos de importación en declaraciones de módulos ambient con patrón. Así, las declaraciones pueden distinguir imports mediante atributos como `type: 'css'` o `type: 'text'`.", 'matching': 'Cuando un import incluye atributos, TypeScript puede resolverlo contra un módulo ambient con patrón que coincida. La coincidencia usa asignabilidad y, si varias declaraciones coinciden, TypeScript elige la que tenga el tipo de atributos más específico.', 'limits': 'Por ahora, los tipos de atributos de estas declaraciones se limitan a propiedades normales cuyos valores sean tipos literales de cadena. Las declaraciones con el mismo patrón y tipos de atributos idénticos pueden fusionarse; los tipos distintos permanecen separados.', 'compat': 'El cambio se integró para el hito TypeScript 7.1.0 Beta. No añade declaraciones integradas para imports CSS o de texto a la biblioteca estándar, por lo que los proyectos y herramientas aún deben definir los módulos ambient que necesiten.', 'head_changed': 'Qué cambió', 'head_compat': 'Compatibilidad', 'head_source': 'Fuente', 'source_intro': 'Lee el pull request de TypeScript que se integró:'}, 'ja-jp': {'title': 'TypeScript 7.1 が ambient module に import attributes を追加', 'description': 'TypeScript 7.1 では、パターン ambient module 宣言を import attributes に基づいて照合できます。', 'published': '**公開日:** 2026年9月1日', 'summary': 'パターン ambient module で import attributes の型を宣言できるようになり、TypeScript は import の属性に応じて型定義を選択できます。', 'what': "TypeScript のネイティブコンパイラは、パターン ambient module 宣言で import attributes の型をサポートするようになりました。これにより、`type: 'css'` や `type: 'text'` などの属性で import を区別できます。", 'matching': 'import に属性がある場合、TypeScript は一致するパターン ambient module に解決できます。照合には代入可能性が使われ、複数の宣言が一致する場合は、最も具体的な属性型を持つ宣言が選択されます。', 'limits': '現時点では、これらの宣言の属性型は、値が文字列リテラル型である通常のプロパティに限定されます。同じパターンと同一の属性型を持つ宣言はマージできますが、異なる属性型は別々に扱われます。', 'compat': 'この変更は TypeScript 7.1.0 Beta マイルストーン向けにマージされました。標準ライブラリに CSS やテキスト import の宣言が組み込まれるわけではないため、プロジェクトやツールは必要な ambient module を引き続き定義する必要があります。', 'head_changed': '変更点', 'head_compat': '互換性', 'head_source': 'ソース', 'source_intro': 'マージされた TypeScript の pull request を参照してください：'}, 'fr-fr': {'title': 'TypeScript 7.1 ajoute les attributs d’import aux modules ambient', 'description': 'TypeScript 7.1 peut faire correspondre les déclarations de modules ambient à motif selon les attributs d’import.', 'published': '**Publié le :** 1er septembre 2026', 'summary': 'Les modules ambient à motif peuvent désormais déclarer des types d’attributs d’import, afin que TypeScript choisisse les types selon les attributs de l’import.', 'what': "Le compilateur natif de TypeScript prend désormais en charge les types d’attributs d’import dans les déclarations de modules ambient à motif. Les déclarations peuvent ainsi distinguer les imports avec des attributs tels que `type: 'css'` ou `type: 'text'`.", 'matching': 'Lorsqu’un import possède des attributs, TypeScript peut le résoudre vers un module ambient à motif correspondant. La correspondance repose sur l’assignabilité et, si plusieurs déclarations correspondent, TypeScript choisit celle dont le type d’attributs est le plus spécifique.', 'limits': 'Pour l’instant, les types d’attributs de ces déclarations sont limités aux propriétés ordinaires dont les valeurs sont des types littéraux de chaîne. Les déclarations ayant le même motif et des types d’attributs identiques peuvent fusionner ; des types différents restent séparés.', 'compat': 'La modification a été intégrée pour le jalon TypeScript 7.1.0 Beta. Elle n’ajoute pas de déclarations intégrées pour les imports CSS ou texte à la bibliothèque standard ; les projets et outils doivent donc toujours définir les modules ambient dont ils ont besoin.', 'head_changed': 'Ce qui change', 'head_compat': 'Compatibilité', 'head_source': 'Source', 'source_intro': 'Consultez la pull request TypeScript fusionnée :'}, 'ko-kr': {'title': 'TypeScript 7.1이 ambient 모듈에 import attributes를 추가했습니다', 'description': 'TypeScript 7.1은 import attributes를 기준으로 패턴 ambient 모듈 선언을 매칭할 수 있습니다.', 'published': '**게시일:** 2026년 9월 1일', 'summary': '패턴 ambient 모듈이 이제 import attributes 타입을 선언할 수 있어 TypeScript가 import의 속성에 따라 타입 정의를 선택할 수 있습니다.', 'what': "TypeScript의 네이티브 컴파일러는 이제 패턴 ambient 모듈 선언에서 import attributes 타입을 지원합니다. 따라서 선언은 `type: 'css'` 또는 `type: 'text'` 같은 속성으로 import를 구분할 수 있습니다.", 'matching': 'import에 속성이 있으면 TypeScript는 일치하는 패턴 ambient 모듈로 해석할 수 있습니다. 매칭에는 할당 가능성이 사용되며, 여러 선언이 일치하면 TypeScript는 가장 구체적인 속성 타입을 가진 선언을 선택합니다.', 'limits': '현재 이러한 선언의 속성 타입은 값이 문자열 리터럴 타입인 일반 프로퍼티로 제한됩니다. 같은 패턴과 동일한 속성 타입을 가진 선언은 병합할 수 있지만, 서로 다른 속성 타입은 분리됩니다.', 'compat': '이 변경은 TypeScript 7.1.0 Beta 마일스톤에 병합되었습니다. 표준 라이브러리에 CSS 또는 텍스트 import 선언을 내장하는 것은 아니므로 프로젝트와 도구는 필요한 ambient 모듈을 계속 정의해야 합니다.', 'head_changed': '변경 사항', 'head_compat': '호환성', 'head_source': '출처', 'source_intro': '병합된 TypeScript pull request를 확인하세요:'}, 'id-id': {'title': 'TypeScript 7.1 menambahkan atribut impor ke modul ambient', 'description': 'TypeScript 7.1 dapat mencocokkan deklarasi modul ambient berpola berdasarkan atribut impor.', 'published': '**Diterbitkan:** 1 September 2026', 'summary': 'Modul ambient berpola kini dapat mendeklarasikan tipe atribut impor, sehingga TypeScript dapat memilih tipe berdasarkan atribut pada import.', 'what': "Kompiler native TypeScript kini mendukung tipe atribut impor pada deklarasi modul ambient berpola. Dengan demikian, deklarasi dapat membedakan import melalui atribut seperti `type: 'css'` atau `type: 'text'`.", 'matching': 'Ketika sebuah import memiliki atribut, TypeScript dapat me-resolve-nya ke modul ambient berpola yang cocok. Pencocokan menggunakan assignability dan, jika lebih dari satu deklarasi cocok, TypeScript memilih deklarasi dengan tipe atribut yang paling spesifik.', 'limits': 'Untuk saat ini, tipe atribut pada deklarasi tersebut dibatasi pada properti biasa yang nilainya berupa tipe literal string. Deklarasi dengan pola dan tipe atribut yang identik dapat digabungkan; tipe atribut yang berbeda tetap terpisah.', 'compat': 'Perubahan ini digabungkan untuk milestone TypeScript 7.1.0 Beta. Perubahan tersebut tidak menambahkan deklarasi import CSS atau teks bawaan ke pustaka standar, sehingga proyek dan tooling tetap perlu mendefinisikan modul ambient yang diperlukan.', 'head_changed': 'Apa yang berubah', 'head_compat': 'Kompatibilitas', 'head_source': 'Sumber', 'source_intro': 'Baca pull request TypeScript yang telah digabungkan:'}, 'de-de': {'title': 'TypeScript 7.1 fügt Importattribute zu Ambient-Modulen hinzu', 'description': 'TypeScript 7.1 kann Pattern-Ambient-Moduldeklarationen anhand von Importattributen zuordnen.', 'published': '**Veröffentlicht:** 1. September 2026', 'summary': 'Pattern-Ambient-Module können nun Typen für Importattribute deklarieren, sodass TypeScript Typen anhand der Attribute eines Imports auswählen kann.', 'what': "Der native TypeScript-Compiler unterstützt jetzt Typen für Importattribute in Pattern-Ambient-Moduldeklarationen. Dadurch können Deklarationen Imports anhand von Attributen wie `type: 'css'` oder `type: 'text'` unterscheiden.", 'matching': 'Wenn ein Import Attribute enthält, kann TypeScript ihn gegen ein passendes Pattern-Ambient-Modul auflösen. Die Zuordnung basiert auf Zuweisbarkeit; passen mehrere Deklarationen, wählt TypeScript die mit dem spezifischsten Attributtyp.', 'limits': 'Vorerst sind Attributtypen in diesen Deklarationen auf normale Eigenschaften beschränkt, deren Werte String-Literaltypen sind. Deklarationen mit demselben Pattern und identischen Attributtypen können zusammengeführt werden; unterschiedliche Attributtypen bleiben getrennt.', 'compat': 'Die Änderung wurde für den Meilenstein TypeScript 7.1.0 Beta zusammengeführt. Sie fügt der Standardbibliothek keine integrierten CSS- oder Text-Importdeklarationen hinzu; Projekte und Tools müssen die benötigten Ambient-Module weiterhin selbst definieren.', 'head_changed': 'Was sich geändert hat', 'head_compat': 'Kompatibilität', 'head_source': 'Quelle', 'source_intro': 'Lesen Sie den zusammengeführten TypeScript-Pull-Request:'}, 'pl-pl': {'title': 'TypeScript 7.1 dodaje atrybuty importu do modułów ambient', 'description': 'TypeScript 7.1 może dopasowywać deklaracje wzorcowych modułów ambient na podstawie atrybutów importu.', 'published': '**Opublikowano:** 1 września 2026 r.', 'summary': 'Wzorcowe moduły ambient mogą teraz deklarować typy atrybutów importu, dzięki czemu TypeScript wybiera typy na podstawie atrybutów importu.', 'what': "Natywny kompilator TypeScript obsługuje teraz typy atrybutów importu w deklaracjach wzorcowych modułów ambient. Dzięki temu deklaracje mogą rozróżniać importy za pomocą atrybutów takich jak `type: 'css'` lub `type: 'text'`.", 'matching': 'Gdy import zawiera atrybuty, TypeScript może rozwiązać go do pasującego wzorcowego modułu ambient. Dopasowanie wykorzystuje przypisywalność, a jeśli pasuje więcej deklaracji, TypeScript wybiera tę z najbardziej szczegółowym typem atrybutów.', 'limits': 'Obecnie typy atrybutów w tych deklaracjach są ograniczone do zwykłych właściwości, których wartości mają typ literału łańcuchowego. Deklaracje z tym samym wzorcem i identycznymi typami atrybutów mogą się łączyć; różne typy pozostają oddzielne.', 'compat': 'Zmiana została scalona dla kamienia milowego TypeScript 7.1.0 Beta. Nie dodaje ona wbudowanych deklaracji importów CSS ani tekstowych do biblioteki standardowej, więc projekty i narzędzia nadal muszą definiować potrzebne moduły ambient.', 'head_changed': 'Co się zmieniło', 'head_compat': 'Zgodność', 'head_source': 'Źródło', 'source_intro': 'Przeczytaj scalony pull request TypeScript:'}, 'tr-tr': {'title': 'TypeScript 7.1 ambient modüllere import öznitelikleri ekliyor', 'description': 'TypeScript 7.1, desenli ambient modül bildirimlerini import özniteliklerine göre eşleştirebilir.', 'published': '**Yayımlandı:** 1 Eylül 2026', 'summary': 'Desenli ambient modüller artık import öznitelik türleri bildirebilir; böylece TypeScript import özniteliklerine göre uygun türleri seçebilir.', 'what': "TypeScript'in yerel derleyicisi artık desenli ambient modül bildirimlerinde import öznitelik türlerini destekliyor. Böylece bildirimler `type: 'css'` veya `type: 'text'` gibi özniteliklerle importları ayırt edebiliyor.", 'matching': 'Bir import öznitelik içerdiğinde TypeScript onu eşleşen desenli bir ambient modüle çözümleyebilir. Eşleştirme atanabilirliği kullanır; birden fazla bildirim eşleşirse TypeScript en özel öznitelik türüne sahip olanı seçer.', 'limits': 'Şimdilik bu bildirimlerdeki öznitelik türleri, değerleri string literal türü olan normal özelliklerle sınırlıdır. Aynı desen ve aynı öznitelik türlerine sahip bildirimler birleştirilebilir; farklı türler ayrı kalır.', 'compat': 'Değişiklik TypeScript 7.1.0 Beta kilometre taşı için birleştirildi. Standart kütüphaneye yerleşik CSS veya metin import bildirimleri eklemez; projeler ve araçlar ihtiyaç duydukları ambient modülleri tanımlamaya devam etmelidir.', 'head_changed': 'Neler değişti', 'head_compat': 'Uyumluluk', 'head_source': 'Kaynak', 'source_intro': "Birleştirilen TypeScript pull request'ini okuyun:"}, 'vi-vn': {'title': 'TypeScript 7.1 thêm thuộc tính import cho ambient module', 'description': 'TypeScript 7.1 có thể khớp khai báo ambient module dạng mẫu dựa trên các thuộc tính import.', 'published': '**Đã xuất bản:** 1 tháng 9, 2026', 'summary': 'Ambient module dạng mẫu giờ có thể khai báo kiểu cho thuộc tính import, giúp TypeScript chọn kiểu dựa trên thuộc tính của import.', 'what': "Trình biên dịch native của TypeScript giờ hỗ trợ kiểu thuộc tính import trong khai báo ambient module dạng mẫu. Nhờ đó, khai báo có thể phân biệt import bằng các thuộc tính như `type: 'css'` hoặc `type: 'text'`.", 'matching': 'Khi một import có thuộc tính, TypeScript có thể phân giải nó tới ambient module dạng mẫu phù hợp. Việc khớp dùng tính gán được; nếu có nhiều khai báo phù hợp, TypeScript chọn khai báo có kiểu thuộc tính cụ thể nhất.', 'limits': 'Hiện tại, kiểu thuộc tính trong các khai báo này chỉ được phép là thuộc tính thông thường có giá trị là kiểu literal chuỗi. Các khai báo có cùng mẫu và kiểu thuộc tính giống hệt nhau có thể hợp nhất; các kiểu khác nhau vẫn tách biệt.', 'compat': 'Thay đổi đã được merge cho milestone TypeScript 7.1.0 Beta. Nó không thêm sẵn khai báo import CSS hoặc văn bản vào thư viện chuẩn, vì vậy dự án và tooling vẫn cần tự định nghĩa các ambient module cần thiết.', 'head_changed': 'Thay đổi', 'head_compat': 'Tương thích', 'head_source': 'Nguồn', 'source_intro': 'Đọc pull request TypeScript đã được merge:'}, 'th-th': {'title': 'TypeScript 7.1 เพิ่ม import attributes ให้ ambient module', 'description': 'TypeScript 7.1 สามารถจับคู่การประกาศ ambient module แบบ pattern ตาม import attributes ได้', 'published': '**เผยแพร่:** 1 กันยายน 2026', 'summary': 'ambient module แบบ pattern สามารถประกาศชนิดของ import attributes ได้แล้ว ทำให้ TypeScript เลือกชนิดตาม attributes ของ import', 'what': "คอมไพเลอร์ native ของ TypeScript รองรับชนิดของ import attributes ในการประกาศ ambient module แบบ pattern แล้ว จึงสามารถแยก import ด้วย attributes เช่น `type: 'css'` หรือ `type: 'text'` ได้", 'matching': 'เมื่อ import มี attributes TypeScript สามารถ resolve ไปยัง ambient module แบบ pattern ที่ตรงกันได้ การจับคู่ใช้ assignability และหากมีหลาย declaration ที่ตรงกัน TypeScript จะเลือก declaration ที่มีชนิด attributes เฉพาะเจาะจงที่สุด', 'limits': 'ในขณะนี้ ชนิดของ attributes ใน declaration เหล่านี้จำกัดอยู่ที่ property ปกติซึ่งมีค่าเป็น string literal type declaration ที่มี pattern และชนิด attributes เหมือนกันสามารถ merge กันได้ ส่วนชนิดที่ต่างกันจะยังแยกจากกัน', 'compat': 'การเปลี่ยนแปลงนี้ถูก merge สำหรับ milestone TypeScript 7.1.0 Beta และไม่ได้เพิ่ม declaration สำหรับ CSS หรือ text import ไว้ใน standard library โดยอัตโนมัติ ดังนั้นโปรเจกต์และ tooling ยังต้องกำหนด ambient module ที่ต้องใช้เอง', 'head_changed': 'สิ่งที่เปลี่ยนแปลง', 'head_compat': 'ความเข้ากันได้', 'head_source': 'แหล่งที่มา', 'source_intro': 'อ่าน pull request ของ TypeScript ที่ merge แล้ว:'}, 'ru-ru': {'title': 'TypeScript 7.1 добавляет import attributes в ambient-модули', 'description': 'TypeScript 7.1 может сопоставлять шаблонные объявления ambient-модулей по import attributes.', 'published': '**Опубликовано:** 1 сентября 2026 г.', 'summary': 'Шаблонные ambient-модули теперь могут объявлять типы import attributes, позволяя TypeScript выбирать типы по атрибутам import.', 'what': "Нативный компилятор TypeScript теперь поддерживает типы import attributes в шаблонных объявлениях ambient-модулей. Благодаря этому объявления могут различать import по атрибутам вроде `type: 'css'` или `type: 'text'`.", 'matching': 'Если import содержит атрибуты, TypeScript может разрешить его через подходящий шаблонный ambient-модуль. Сопоставление использует assignability; если подходят несколько объявлений, TypeScript выбирает объявление с наиболее конкретным типом атрибутов.', 'limits': 'Пока типы атрибутов в таких объявлениях ограничены обычными свойствами, значения которых имеют строковые литеральные типы. Объявления с одинаковым шаблоном и идентичными типами атрибутов могут объединяться; разные типы остаются раздельными.', 'compat': 'Изменение объединено для этапа TypeScript 7.1.0 Beta. Оно не добавляет встроенные объявления CSS- или текстовых import в стандартную библиотеку, поэтому проекты и инструменты по-прежнему должны определять нужные ambient-модули.', 'head_changed': 'Что изменилось', 'head_compat': 'Совместимость', 'head_source': 'Источник', 'source_intro': 'Прочитайте объединённый pull request TypeScript:'}, 'ar': {'title': 'TypeScript 7.1 يضيف سمات الاستيراد إلى الوحدات المحيطية', 'description': 'يمكن لـ TypeScript 7.1 مطابقة تصريحات الوحدات المحيطية ذات الأنماط اعتمادًا على سمات الاستيراد.', 'published': '**تاريخ النشر:** 1 سبتمبر 2026', 'summary': 'يمكن الآن للوحدات المحيطية ذات الأنماط التصريح بأنواع سمات الاستيراد، مما يسمح لـ TypeScript باختيار الأنواع وفق سمات import.', 'what': "يدعم المترجم الأصلي في TypeScript الآن أنواع سمات الاستيراد في تصريحات الوحدات المحيطية ذات الأنماط. وبذلك يمكن للتصريحات التمييز بين عمليات import باستخدام سمات مثل `type: 'css'` أو `type: 'text'`.", 'matching': 'عندما تحتوي عملية import على سمات، يمكن لـ TypeScript حلها إلى وحدة محيطية ذات نمط مطابق. تعتمد المطابقة على قابلية الإسناد، وإذا تطابقت عدة تصريحات يختار TypeScript التصريح ذي نوع السمات الأكثر تحديدًا.', 'limits': 'في الوقت الحالي تقتصر أنواع السمات في هذه التصريحات على الخصائص العادية التي تكون قيمها من أنواع السلاسل الحرفية. يمكن دمج التصريحات ذات النمط نفسه وأنواع السمات المتطابقة، بينما تظل الأنواع المختلفة منفصلة.', 'compat': 'دُمج التغيير ضمن milestone الخاص بـ TypeScript 7.1.0 Beta. ولا يضيف تصريحات مضمّنة لاستيراد CSS أو النصوص إلى المكتبة القياسية، لذلك ما زالت المشاريع والأدوات بحاجة إلى تعريف الوحدات المحيطية المطلوبة.', 'head_changed': 'ما الذي تغيّر', 'head_compat': 'التوافق', 'head_source': 'المصدر', 'source_intro': 'اقرأ طلب السحب المدمج في TypeScript:'}}

def configured_locales():
    text = LOCALES_FILE.read_text(encoding="utf-8")
    keys = ["root"]
    keys += re.findall(r"^\s*'([^']+)':\s*\{", text, re.M)
    return keys

def news_dir(locale):
    return DOCS / "typescript-news" if locale == "root" else DOCS / locale / "typescript-news"

def article_text(d):
    return f"""---
title: {d['title']}
description: {d['description']}
lastUpdated: {DATE}
sidebar:
    order: 1
head:
    - tag: meta
      attrs:
          property: article:published_time
          content: '{DATE}'
---

{d['published']}

{d['what']}

## {d['head_changed']}

{d['matching']}

{d['limits']}

## {d['head_compat']}

{d['compat']}

## {d['head_source']}

{d['source_intro']} [Support import attributes on ambient modules]({SOURCE}).
"""

def index_entry(d):
    return f"""### [{d['title']}](./2026/{SLUG}/)

{d['published']}

{d['summary']}

"""

def main():
    configured = configured_locales()
    if set(configured) != set(DATA):
        missing = sorted(set(configured) - set(DATA))
        extra = sorted(set(DATA) - set(configured))
        raise SystemExit(f"Locale mismatch. Missing={missing} extra={extra}")

    for locale in configured:
        nd = news_dir(locale)
        if not nd.exists():
            raise SystemExit(f"Missing TypeScript News directory for {locale}: {nd}")
        year_dirs = sorted(p for p in nd.iterdir() if p.is_dir() and re.fullmatch(r"\d{4}", p.name))
        for yd in year_dirs:
            for path in sorted(yd.glob("*.md")):
                if path.stem == SLUG:
                    continue
                text = path.read_text(encoding="utf-8")
                m = re.search(r"(sidebar:\n\s+order:\s+)(\d+)", text)
                if not m:
                    raise SystemExit(f"Missing sidebar.order in {path}")
                old = int(m.group(2))
                text = text[:m.start(2)] + str(old + 1) + text[m.end(2):]
                path.write_text(text, encoding="utf-8")

    for locale in configured:
        d = DATA[locale]
        nd = news_dir(locale)
        year = nd / "2026"
        year.mkdir(parents=True, exist_ok=True)
        article = year / f"{SLUG}.md"
        if article.exists():
            raise SystemExit(f"Article already exists: {article}")
        article.write_text(article_text(d), encoding="utf-8")

        index = nd / "index.md"
        text = index.read_text(encoding="utf-8")
        if SLUG in text:
            raise SystemExit(f"Index already contains {SLUG}: {index}")
        m = re.search(r"\n## [^\n]+\n\n", text)
        if not m:
            raise SystemExit(f"Could not find latest-news heading in {index}")
        text = text[:m.end()] + index_entry(d) + text[m.end():]
        index.write_text(text, encoding="utf-8")

    workflow = REPO / ".github/workflows/agent-typescript-news-generator.yml"
    helper = Path(__file__)
    workflow.unlink(missing_ok=True)
    helper.unlink(missing_ok=True)

if __name__ == "__main__":
    main()
